//! Original Aero-inspired cruiser mesh. Y up, +Z forward, meters. Generated by generate_motorcycle_mesh.py.
#![allow(clippy::excessive_precision)]
use super::{GeometryTag, MeshBuffer, MeshBuilder, VertexMeta, WorldVertex};
use glam::{Mat4, Vec3};
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MotorcyclePart {
    Body,
    Steering,
    FrontWheel,
    RearWheel,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Default)]
pub enum MotorcyclePaint {
    #[default]
    GreenBlack,
    BurgundyBlack,
    CreamBlack,
    MidnightBlue,
    MatteBlack,
}
impl MotorcyclePaint {
    pub fn palette(self) -> [[u8; 3]; 3] {
        match self {
            Self::GreenBlack => [[38, 91, 67], [24, 29, 30], [172, 144, 82]],
            Self::BurgundyBlack => [[113, 35, 43], [25, 27, 29], [177, 143, 79]],
            Self::CreamBlack => [[204, 190, 154], [27, 31, 31], [151, 117, 60]],
            Self::MidnightBlue => [[41, 69, 105], [22, 27, 33], [151, 166, 177]],
            Self::MatteBlack => [[49, 51, 51], [20, 22, 23], [105, 105, 103]],
        }
    }
}
const FIXED: [[u8; 3]; 12] = [
    [31, 32, 32],
    [15, 17, 17],
    [52, 55, 53],
    [155, 163, 163],
    [204, 210, 207],
    [98, 106, 106],
    [72, 75, 73],
    [207, 200, 165],
    [137, 40, 32],
    [203, 121, 37],
    [31, 27, 24],
    [106, 110, 106],
];
pub fn motorcycle_part_pivot(part: MotorcyclePart) -> Vec3 {
    match part {
        MotorcyclePart::Body => Vec3::new(0.000000, 0.000000, 0.000000),
        MotorcyclePart::Steering => Vec3::new(0.000000, 0.990000, 0.480000),
        MotorcyclePart::FrontWheel => Vec3::new(0.000000, 0.350000, 0.835000),
        MotorcyclePart::RearWheel => Vec3::new(0.000000, 0.345000, -0.835000),
    }
}
type Face = (u32, u32, u32, u8);
pub fn motorcycle_part_mesh(part: MotorcyclePart, paint: MotorcyclePaint) -> MeshBuffer {
    let (points, faces): (&[[f32; 3]], &[Face]) = match part {
        MotorcyclePart::Body => (BODY_POINTS, BODY_FACES),
        MotorcyclePart::Steering => (STEERING_POINTS, STEERING_FACES),
        MotorcyclePart::FrontWheel => (FRONT_WHEEL_POINTS, FRONT_WHEEL_FACES),
        MotorcyclePart::RearWheel => (REAR_WHEEL_POINTS, REAR_WHEEL_FACES),
    };
    let palette = paint.palette();
    let meta = VertexMeta::DEFAULT.with_tag(GeometryTag::Prop);
    let mut b = MeshBuilder::with_capacity(faces.len() * 3, faces.len() * 3);
    for &(a, c, d, m) in faces {
        let [r, g, blue] = if m < 3 {
            palette[m as usize]
        } else {
            FIXED[m as usize - 3]
        };
        b.push_triangle(
            Vec3::from_array(points[a as usize]),
            Vec3::from_array(points[c as usize]),
            Vec3::from_array(points[d as usize]),
            WorldVertex::rgba8(r, g, blue, 255),
            meta,
        );
    }
    b.build()
}
pub fn motorcycle_mesh(paint: MotorcyclePaint) -> MeshBuffer {
    let mut mesh = MeshBuffer::new();
    for part in [
        MotorcyclePart::Body,
        MotorcyclePart::Steering,
        MotorcyclePart::FrontWheel,
        MotorcyclePart::RearWheel,
    ] {
        mesh.append_transformed(
            &motorcycle_part_mesh(part, paint),
            Mat4::from_translation(motorcycle_part_pivot(part)),
        );
    }
    mesh
}
/// Rider attachment points on the cruiser.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MotorcycleLocator {
    Seat,
    GripLeft,
    GripRight,
    FootboardLeft,
    FootboardRight,
}

/// Parent part and offset from its pivot, in model meters.
#[must_use]
pub fn motorcycle_locator(locator: MotorcycleLocator) -> (MotorcyclePart, Vec3) {
    match locator {
        MotorcycleLocator::Seat => (MotorcyclePart::Body, Vec3::new(0.0, 0.752, -0.34)),
        MotorcycleLocator::GripLeft => (MotorcyclePart::Steering, Vec3::new(0.3875, 0.19, -0.2625)),
        MotorcycleLocator::GripRight => {
            (MotorcyclePart::Steering, Vec3::new(-0.3875, 0.19, -0.2625))
        }
        MotorcycleLocator::FootboardLeft => (MotorcyclePart::Body, Vec3::new(0.224, 0.303, 0.16)),
        MotorcycleLocator::FootboardRight => (MotorcyclePart::Body, Vec3::new(-0.224, 0.303, 0.16)),
    }
}
